// Get the message text from the Telegram trigger
const messageInputText = $input.first().json.telegram.message?.text || $input.first().json.telegram.message?.caption

const messageText = messageInputText.toLowerCase().trim();
const ingredientsGreeting = $input.first().json.ingredientsGreeting
const productsGreeting = $input.first().json.productsGreeting


let selectedMode = '';
var responseMessage;

switch (messageText) {
  case 'product':
  case 'products':
    selectedMode = 'PRODUCT';
    responseMessage = productsGreeting;
    break;

  case 'ingredient':
  case 'ingredients':
    selectedMode = 'INGREDIENT';
    responseMessage = ingredientsGreeting;
    break;

  case 'recipe':
  case 'recipes':
    selectedMode = 'RECIPE';
    responseMessage = 'Entering 🍳 *Recipe Mode*. Link ingredients to products and calculate costs.';
    break;

  case 'exit':
  case 'main':
  case 'quit':
    selectedMode = 'MAIN';
    responseMessage = 'Returning to *Main Mode*. Standard POS commands active.';
    break;

  default:
    // If it's not a mode-switch command, we keep the current state
    // This allows the message to pass through to the Regex Router
    return [{
      json: {
        isModeSwitch: false,
        text: messageText
      }
    }];
}

// Return the new state data
return [{
  json: {
    isModeSwitch: true,
    newMode: selectedMode,
    telegramReply: responseMessage,
    chatId: $input.first().json.telegram.message.chat.id
  }
}];

const msg = $input.first().json.telegram;
const messageData = msg.telegram 

if (!messageData) return [];

const rawText = messageData.text || messageData.caption || "";
const cleanText = rawText.trim();
const parts = cleanText.split(' ');

if (parts[0].toLowerCase() === 'add') {
  parts.shift(); // Remove the "add" command from the array

  if (parts.length >= 2) {
    const priceStr = parts.pop(); 

    // Capitalize each word properly
    const name = parts.join(' ')
        .split(' ')
        .filter(word => word.length > 0) // Remove extra spaces
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');

    const price = parseFloat(priceStr.replace(/[^0-9.]/g, '')) || 0;

    return { 
        json: {
            product_name: name,
            product_price: price,
            original_msg_id: messageData.message_id,
            chat_id: messageData.chat.id,
            file_id: (messageData.photo && messageData.photo.length > 0) 
                    ? messageData.photo[messageData.photo.length - 1].file_id 
                    : null
        } 
    };
  }
}

return [];

